<?php
require_once __DIR__ . '/mis_functions.php';
$user = mis_require_employee();
[$start, $end] = mis_period();
$daily = mis_fetch_daily_sales($pdo, $start, $end);
$products = mis_fetch_top_products($pdo, $start, $end, 'revenue', 12);
$totalRevenue = array_sum(array_column($daily, 'revenue'));
$totalOrders = array_sum(array_column($daily, 'orders_count'));
$totalUnits = array_sum(array_column($daily, 'units_sold'));
$averageOrder = $totalOrders > 0 ? $totalRevenue / $totalOrders : 0;
$maxRevenue = max(1, ...array_map(static fn($r) => (float)$r['revenue'], $products ?: [['revenue' => 0]]));
$rowsDescending = array_reverse($daily);
$pageTitle = 'Analisis penjualan';
include __DIR__ . '/layout_top.php';
?>
<header class="page-header"><div><div class="eyebrow">MIS / PENJUALAN</div><h1>Analisis penjualan</h1><p class="muted">Lihat pergerakan omzet, jumlah pesanan, unit terjual, dan kontribusi produk berdasarkan periode.</p></div><div class="page-actions"><?php if (has_any(['manager','admin'])): ?><a class="btn primary" href="mis_export.php?report=sales&start=<?= e($start) ?>&end=<?= e($end) ?>">Unduh CSV ↓</a><?php endif; ?></div></header>
<section class="mis-filter-card"><form method="get" class="mis-filter-form"><div><label for="start">Tanggal mulai</label><input id="start" type="date" name="start" value="<?= e($start) ?>" required></div><div><label for="end">Tanggal akhir</label><input id="end" type="date" name="end" value="<?= e($end) ?>" required></div><button class="btn primary" type="submit">Terapkan filter</button><a class="btn ghost" href="mis_sales.php">30 hari terakhir</a></form><div class="mis-period-note">Periode: <strong><?= e(mis_date_label($start, $end)) ?></strong> · Pendapatan hanya menghitung order lunas yang tidak dibatalkan.</div></section>
<section class="mis-stat-grid"><article class="stat-card"><span class="stat-icon purple">Rp</span><div><small>Total pendapatan</small><strong><?= rupiah($totalRevenue) ?></strong><em>Dari order lunas</em></div></article><article class="stat-card"><span class="stat-icon blue">▤</span><div><small>Pesanan lunas</small><strong><?= mis_number($totalOrders) ?></strong><em>Jumlah transaksi</em></div></article><article class="stat-card"><span class="stat-icon green">▦</span><div><small>Unit terjual</small><strong><?= mis_number($totalUnits) ?></strong><em>Total quantity item</em></div></article><article class="stat-card"><span class="stat-icon red">↗</span><div><small>Rata-rata per pesanan</small><strong><?= rupiah($averageOrder) ?></strong><em>Pendapatan ÷ pesanan</em></div></article></section>
<section class="panel-card"><div class="panel-heading"><div><h2>Grafik tren penjualan harian</h2><p>Setiap titik menunjukkan pendapatan pada tanggal tersebut. Arahkan kursor ke titik untuk melihat rincian.</p></div></div><div class="mis-chart-wrap"><?= mis_svg_sales_chart($daily) ?></div></section>
<section class="panel-card"><div class="panel-heading"><div><h2>Rincian harian</h2><p>Satu baris mewakili satu tanggal, termasuk tanggal tanpa transaksi.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Pesanan</th><th>Unit terjual</th><th>Pendapatan</th><th>Rata-rata / pesanan</th></tr></thead><tbody><?php foreach ($rowsDescending as $row): ?><tr><td><strong><?= e(date('d M Y', strtotime($row['sales_date']))) ?></strong></td><td><?= mis_number($row['orders_count']) ?></td><td><?= mis_number($row['units_sold']) ?></td><td><strong><?= rupiah($row['revenue']) ?></strong></td><td><?= rupiah((int)$row['orders_count'] > 0 ? $row['revenue'] / $row['orders_count'] : 0) ?></td></tr><?php endforeach; ?><?php if (!$rowsDescending): ?><tr><td colspan="5" class="center muted">Tidak ada data pada periode ini.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel-card"><div class="panel-heading"><div><h2>Produk dengan kontribusi pendapatan tertinggi</h2><p>Pendapatan dihitung dari subtotal item pada order lunas.</p></div><a class="text-link" href="mis_products.php?start=<?= e($start) ?>&end=<?= e($end) ?>&metric=revenue">Buka analisis produk →</a></div><?php if ($products): ?><div class="mis-hbar-list"><?php foreach ($products as $row): $width = ((float)$row['revenue'] / $maxRevenue) * 100; ?><div class="mis-hbar-item"><div class="mis-hbar-label"><strong><?= e($row['product_name']) ?></strong><b><?= rupiah($row['revenue']) ?></b></div><div class="mis-hbar-track"><span class="mis-hbar-fill" style="width:<?= e(number_format($width, 2, '.', '')) ?>%"></span></div><div class="mis-hbar-meta"><?= mis_number($row['units_sold']) ?> unit terjual</div></div><?php endforeach; ?></div><?php else: ?><div class="mis-empty-chart">Belum ada produk terjual pada periode ini.</div><?php endif; ?></section>
<?php include __DIR__ . '/layout_bottom.php'; ?>
